def bits_of(b):
    return [(b[i//8]>>(7-(i%8)))&1 for i in range(64)]
def bytes_of(bits):
    out=bytearray(8)
    for i,bit in enumerate(bits):
        if bit: out[i//8]|=1<<(7-(i%8))
    return bytes(out)
def perm(b, P):
    bits=bits_of(b)
    return bytes_of([bits[p-1] for p in P])
def inv(P):
    r=[0]*len(P)
    for i,p in enumerate(P): r[p-1]=i+1
    return r
